import { HttpClient } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";
import { catchError, finalize, tap, throwError } from "rxjs";

import { User } from "@store/userStore";
import { environment } from "@env/environment.development";
import { OptimisticService } from "@shared/services/optimistic.service";
import { NotificationService } from "@shared/services/notification.service";

@Injectable({
  providedIn: "root",
})
export class AdmUserService {
  constructor() {}

  private http = inject(HttpClient);
  private optimisicService = inject(OptimisticService);
  private notificationService = inject(NotificationService);

  fetchUsers() {
    return this.http.get<User[]>(`${environment.apiUrl}/user`);
  }

  addUser(user: User) {
    this.optimisicService.setLoadingState("user", user.id, true, "creating");
    this.notificationService.showToast(
      "info",
      `${user.username}`,
      "Creando usuario",
    );
    return this.http
      .post<User>(`${environment.apiUrl}/auth/register`, user)
      .pipe(
        tap(() => {
          this.notificationService.showToast(
            "success",
            `${user.username}`,
            "Usuario creado",
          );
        }),
        catchError((error) => {
          this.notificationService.showToast(
            "error",
            `${user.username}`,
            "Error creando usuario",
          );
          return throwError(() => error);
        }),
        finalize(() => {
          this.optimisicService.setLoadingState("user", user.id, false);
        }),
      );
  }

  updateUser(user: Omit<User, "token" | "password">) {
    this.optimisicService.setLoadingState("user", user.id, true, "updating");
    this.notificationService.showToast(
      "info",
      `${user.username}`,
      "Actualizando usuario",
    );

    return this.http
      .patch<User>(`${environment.apiUrl}/users/${user.id}`, user)
      .pipe(
        tap(() => {
          this.notificationService.showToast(
            "success",
            `${user.username}`,
            "Usuario actualizado",
          );
        }),
        catchError((error) => {
          this.notificationService.showToast(
            "error",
            `${user.username}`,
            "Error actualizando usuario",
          );
          return throwError(() => error);
        }),
        finalize(() => {
          this.optimisicService.setLoadingState("user", user.id, false);
        }),
      );
  }

  deleteUser(user: User) {
    this.optimisicService.setLoadingState("user", user.id, true, "deleting");

    this.notificationService.showToast(
      "info",
      `${user.username}`,
      "Eliminando usuario",
    );

    return this.http.delete(`${environment.apiUrl}/users/${user.id}`).pipe(
      tap(() => {
        this.notificationService.showToast(
          "success",
          `${user.username}`,
          "Usuario eliminado",
        );
      }),
      catchError((error) => {
        this.notificationService.showToast(
          "error",
          `${user.username}`,
          "Error eliminando usuario",
        );
        return throwError(() => error);
      }),
      finalize(() => {
        this.optimisicService.setLoadingState("user", user.id, false);
      }),
    );
  }

  getToken() {
    return localStorage.getItem("token");
  }
}
