Hay varias formas de mejorar el servicio de notificaciones para lograr lo que necesitas. Te propongo dos soluciones:

1. **Solución 1**: Modificar la notificación existente
Esta solución mantiene una única notificación y actualiza su estado:

```typescript
// notification.service.ts
@Injectable({
  providedIn: 'root',
})
export class NotificationService {
  private messageService = inject(MessageService);
  private activeNotifications = new Map<string, string>(); // Para trackear notificaciones activas

  showToast(
    severity: "success" | "info" | "warn" | "error" | "contrast" | "secondary",
    summary: string,
    detail: string,
    life: number = 6000,
    key?: string // Identificador único para la notificación
  ) {
    if (key) {
      this.messageService.clear(key);
      this.activeNotifications.set(key, summary);
    }

    this.messageService.add({ 
      severity, 
      summary, 
      detail, 
      life,
      key
    });
  }

  updateToast(
    key: string,
    severity: "success" | "info" | "warn" | "error" | "contrast" | "secondary",
    detail: string,
    life: number = 6000
  ) {
    const summary = this.activeNotifications.get(key);
    if (summary) {
      this.messageService.clear(key);
      this.messageService.add({ 
        key,
        severity, 
        summary, 
        detail, 
        life 
      });
      this.activeNotifications.delete(key);
    }
  }

  clear(key?: string) {
    this.messageService.clear(key);
    if (key) {
      this.activeNotifications.delete(key);
    }
  }
}
```

